.tpl-hf-split-cards { position: relative; width: 100%; height: 100%; overflow: hidden; display: flex; flex-direction: column; align-items: center; justify-content: center; background: radial-gradient(60% 60% at 24% 55%, rgba(24,217,232,0.14) 0%, transparent 70%), radial-gradient(60% 60% at 76% 55%, rgba(34,197,94,0.14) 0%, transparent 70%), var(--bg, #070b14); font-family: var(--font-sans, 'Inter', 'PingFang SC', sans-serif); color: var(--fg, #ffffff); }
.tpl-hf-split-cards .bg-grid { position: absolute; inset: 0; background-image: linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px); background-size: 64px 64px; mask-image: radial-gradient(ellipse at center, black 35%, transparent 80%); pointer-events: none; }
.tpl-hf-split-cards .split-title { position: relative; z-index: 3; font-size: clamp(26px, 4.4vmin, 56px); font-weight: 800; letter-spacing: -0.02em; margin-bottom: clamp(18px, 3.8vh, 46px); text-align: center; padding: 0 6%; opacity: 0; }
.tpl-hf-split-cards .cards-row { position: relative; z-index: 2; display: flex; flex-wrap: wrap; align-items: stretch; justify-content: center; gap: clamp(20px, 4vw, 64px); width: 88%; max-width: 1480px; perspective: 1100px; transform-style: preserve-3d; }
.tpl-hf-split-cards .card-pos { flex: 1 1 320px; max-width: 640px; min-width: 260px; transform-style: preserve-3d; opacity: 0; }
.tpl-hf-split-cards .card-tilt { transform-style: preserve-3d; }
.tpl-hf-split-cards .card-left .card-tilt { transform-origin: 100% 50%; }
.tpl-hf-split-cards .card-right .card-tilt { transform-origin: 0% 50%; }
.tpl-hf-split-cards .card-surface { border-radius: 22px; overflow: hidden; border: 1px solid rgba(255,255,255,0.14); padding: clamp(18px, 3vmin, 34px); backdrop-filter: blur(18px); position: relative; }
.tpl-hf-split-cards .card-left .card-surface { background: linear-gradient(140deg, rgba(12,38,48,0.92), rgba(16,60,64,0.85)); box-shadow: 24px 26px 56px rgba(0,0,0,0.45), 0 0 44px rgba(24,217,232,0.18); }
.tpl-hf-split-cards .card-right .card-surface { background: linear-gradient(140deg, rgba(14,34,26,0.92), rgba(22,64,44,0.85)); box-shadow: -24px 26px 56px rgba(0,0,0,0.45), 0 0 44px rgba(34,197,94,0.18); }
.tpl-hf-split-cards .card-badge { display: inline-block; padding: 0.35em 0.9em; border-radius: 999px; font-size: clamp(12px, 1.5vmin, 17px); font-weight: 700; letter-spacing: 0.04em; margin-bottom: 14px; opacity: 0; }
.tpl-hf-split-cards .card-left .card-badge { background: rgba(24,217,232,0.16); color: #67e8f9; border: 1px solid rgba(24,217,232,0.45); }
.tpl-hf-split-cards .card-right .card-badge { background: rgba(34,197,94,0.18); color: #86efac; border: 1px solid rgba(34,197,94,0.45); }
.tpl-hf-split-cards .mock-window { height: clamp(110px, 21vh, 230px); border-radius: 14px; border: 1px solid rgba(255,255,255,0.09); background: rgba(6,10,18,0.58); padding: 14px; display: flex; flex-direction: column; justify-content: space-between; margin-bottom: 16px; }
.tpl-hf-split-cards .mock-bars { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; flex: 1; margin-top: 8px; }
.tpl-hf-split-cards .mock-tile { border-radius: 8px; background: rgba(24,217,232,0.12); border: 1px solid rgba(24,217,232,0.22); }
.tpl-hf-split-cards .card-right .mock-tile { background: rgba(34,197,94,0.12); border-color: rgba(34,197,94,0.25); }
.tpl-hf-split-cards .card-h { font-size: clamp(22px, 3.2vmin, 38px); font-weight: 800; line-height: 1.2; }
.tpl-hf-split-cards .card-sub { margin-top: 8px; font-size: clamp(14px, 1.9vmin, 21px); color: var(--muted, #cbd5e1); line-height: 1.45; }
